                if (result.size() == n) {
                    break;
                }
            }
        }

        if (result.size() >= n) {
            return;
        }

        List<Integer> nextLevel2 = new ArrayList<>();
        for (int num : result) {
            int lastDigit = num % 10;
            if (lastDigit == 9) {
                nextLevel2.add(num / 10);
            } else {
                nextLevel2.add(num * 10 + lastDigit + 1);
            }
        }

        recursiveGenerateLexicalOrder(result, n, nextLevel2);
