public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;
    while (current <= n) {
        result.add(current);
        int temp = current * 10;
        if (temp > n) break;
        current = temp;
    }
    return result;
}

